/**
 * Patches msg.payload.content with a receiver notice if any files failed.
 * Runs after upload placeholder — metadata.files.failed is complete.
 */
const failed = msg.metadata.files.failed;

if (failed.length === 0) return msg;

const succeeded = msg.metadata.files.items.length;
const total = succeeded + failed.length;
const notice = " [" + failed.length + "/" + total
    + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.content = (msg.payload.content || "") + notice;

return msg;

/**                                                                                                                                                                                              
 * Reads downloaded file buffers from global context and                                                                                                                                         
 * builds a raw multipart/form-data request body for the WaSOS v1 API.                                                                                                                           
 */
const utils = global.get("utils");
const items = msg.metadata.files.items;
const failed = msg.metadata.files.failed || [];
const uploaded = [];
const buffers = [];

// Derive MIME type from filename extension                                                                                                                                                      
// (Rayvn API returns application/octet-stream which WaSOS rejects)                                                                                                                              
function getMimeType(filename) {
    const ext = (filename || "").split('.').pop().toLowerCase();
    const types = {
        jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png",
        gif: "image/gif", webp: "image/webp", bmp: "image/bmp",
        svg: "image/svg+xml", heic: "image/heic",
        pdf: "application/pdf",
        mp4: "video/mp4", mov: "video/quicktime", avi: "video/x-msvideo",
        mp3: "audio/mpeg", wav: "audio/wav",
        doc: "application/msword", txt: "text/plain", csv: "text/csv",
        docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        zip: "application/zip"
    };
    return types[ext] || null;
}

items.forEach(file => {
    const buffer = file.context_key
        ? global.get("files." + file.context_key)
        : null;

    if (!buffer || buffer.length === 0) {
        failed.push({
            name: file.name || "ukjent fil",
            reason: utils.FILE_REASONS.DOWNLOAD_FAILED
        });
        if (file.context_key) global.set("files." + file.context_key, undefined);
        return;
    }

    const mime = getMimeType(file.name) || file.type || "application/octet-stream";

    buffers.push({ file, buffer, mime });
    uploaded.push(file);
    global.set("files." + file.context_key, undefined);
});

if (buffers.length > 0) {
    const boundary = "----PBridge" + Date.now();
    const CRLF = "\r\n";
    const parts = [];

    parts.push(Buffer.from(
        "--" + boundary + CRLF +
        "Content-Disposition: form-data; name=\"content\"" + CRLF + CRLF +
        (msg.payload.content || "") + CRLF
    ));

    if (msg.payload.callsign) {
        parts.push(Buffer.from(
            "--" + boundary + CRLF +
            "Content-Disposition: form-data; name=\"callsign\"" + CRLF + CRLF +
            msg.payload.callsign + CRLF
        ));
    }

    buffers.forEach(function (item) {
        var fname = item.file.name || "unknown_file";
        parts.push(Buffer.from(
            "--" + boundary + CRLF +
            "Content-Disposition: form-data; name=\"files\"; filename=\"" + fname + "\"" + CRLF +
            "Content-Type: " + item.mime + CRLF + CRLF
        ));
        parts.push(item.buffer);
        parts.push(Buffer.from(CRLF));
    });

    parts.push(Buffer.from("--" + boundary + "--" + CRLF));

    msg.payload = Buffer.concat(parts);
    msg.headers = {
        "Content-Type": "multipart/form-data; boundary=" + boundary
    };
    msg._multipart = true;
} else {
    msg.payload.files = [];
}

msg.metadata.files.items = uploaded;
msg.metadata.files.failed = failed;

return msg;
